INSERT INTO "public"."modules" ("id", "name", "module_type", "description", "config_schema", "created_at", "updated_at") VALUES
	('5f81da18-4dbe-41c0-9dad-9da34f701705', 'Phrase Recognition', 'PHRASE_RECOGNITION', 'Student sees an Indonesian phrase/idiom/expression and selects the correct English equivalent from a calibrated dropdown of 10 options. Auto-graded. Source: Vocabulary Vault (word_type IN Idiom, Proverb, Expression, Phrase).', '{"answer_type": "dropdown", "source_types": ["Idiom", "Proverb", "Expression", "Phrase"], "options_count": 10, "time_limit_seconds": 15}', '2026-09-30 19:14:49.027638+00', '2026-09-30 19:14:49.027638+00'),
	('05c135f9-75cb-44ce-a546-b6ff5b1b47b9', 'Tell Me What You See (Visual Pronouns)', 'VISUAL_PRONOUNS', '[DEPRECATED - Gunakan POINT_AND_SPEAK] [DEPRECATED - Gunakan POINT_AND_SPEAK] Student takes a live photo and speaks a description using correct demonstrative pronoun, to-be, article, adjectives, and noun.', '{}', '2026-09-20 15:21:47.560238+00', '2026-09-20 15:21:47.560238+00'),
	('13456a9a-5e90-4d71-a87f-4b7b520b804e', 'Let me tell you something (Narrative Tense)', 'NARRATIVE_TENSE', '[DEPRECATED - Gunakan STORYTELLING] [DEPRECATED - Gunakan STORYTELLING] Student describes an event or tells a story in past/narrative tense.', '{}', '2026-09-20 15:21:47.560238+00', '2026-09-20 15:21:47.560238+00'),
	('90cecb70-3f83-44ca-bf07-b9dc070aaf01', 'Point & Speak!', 'POINT_AND_SPEAK', 'Student takes a live photo and speaks a description using correct demonstrative pronoun, to-be, article, adjectives, and noun.', '{}', '2026-09-20 16:33:58.31018+00', '2026-09-20 16:33:58.31018+00'),
	('25974dcf-062b-4f85-91bd-37a7cf558ab0', 'Storytelling', 'STORYTELLING', 'Highly flexible storytelling engine assessing student stories against configured constraints (duration, sentences, tense, pillars).', '{}', '2026-09-20 16:33:58.31018+00', '2026-09-20 16:33:58.31018+00'),
	('c79af460-0839-46a9-a4c2-0f0917639271', 'Conversation-based', 'CONVERSATIONAL', 'Open conversational module.', '{}', '2026-09-20 15:21:47.560238+00', '2026-09-20 15:21:47.560238+00'),
	('28dd8f23-b980-4b92-bc5f-43938768edbe', 'Multiple Choice', 'MULTIPLE_CHOICE', 'Standard multiple choice quiz.', '{}', '2026-09-20 15:21:47.560238+00', '2026-09-20 15:21:47.560238+00'),
	('99fb7be8-7623-489b-b26e-70c7ba26b1fa', 'Read Aloud / Pronunciation', 'READ_ALOUD', 'Student reads text aloud for pronunciation and fluency scoring.', '{}', '2026-09-20 15:21:47.560238+00', '2026-09-20 15:21:47.560238+00'),
	('c590c69f-44dc-4d26-9c19-263c6e7cbbec', 'Turn-based Roleplay (Realtime/WebSockets)', 'TURN_BASED_ROLEPLAY', 'Interactive realtime AI roleplay.', '{}', '2026-09-20 15:21:47.560238+00', '2026-09-20 15:21:47.560238+00'),
	('b8f3c849-5adf-4b50-b89a-27046d2adad6', 'Speaking Performance (5 Pillars)', 'SPEAKING_MONOLOGUE', 'Full speaking evaluation on 5 pillars (Fluency, Pronunciation, Vocab, Grammar, Comprehension).', '{}', '2026-09-20 15:21:47.560238+00', '2026-09-20 15:21:47.560238+00'),
	('4a57ae11-9e60-461f-969a-0c4ba7981681', 'Vocabulary Mastery', 'VOCAB_MASTERY', 'Vocabulary and spelling evaluation.', '{}', '2026-09-20 15:21:47.560238+00', '2026-09-20 15:21:47.560238+00'),
	('00000000-0000-0000-0000-000000000099', 'Legacy Exam', 'LEGACY_EXAM', 'Migrated legacy exams that have not been assigned to a specific AI module.', '{}', '2026-10-05 17:08:56.616978+00', '2026-10-05 17:08:56.616978+00'),
	('c8922c6a-d64b-4dc8-91ea-df272a149bd2', 'Pair Storytelling', 'PAIR_STORYTELLING', 'Two students independently record story retelling sessions on their own devices. The system links them via a shared pair_session_id. Topics are auto-aggregated from previous Task IDs. Each student is evaluated individually (tense, duration, topic coverage), and results are shown as a combined pair report.', '{"format": "paired_independent", "result_view": "individual_plus_combined", "topic_source": "aggregated_from_tasks", "pair_matching": "manual_or_auto", "min_duration_sec": 3600, "elements_to_assess": ["tense_consistency", "topic_coverage", "fluency", "duration"]}', '2026-09-30 19:15:57.047353+00', '2026-09-30 19:15:57.047353+00');
