	('6a0d2751-c8fa-45b8-81d7-a38f90eefa42', 'Building Your Professional Identity', 'memiliki motivasi diri', 'self-motivated / self-driven', 'Adjective', '2026-10-03 18:12:24.759+00', '2026-10-03 18:12:24.759+00', NULL, 3, 'Workplace', 'A', '1'),
	('1478bca5-cf03-4f9e-bbfe-b80306987d58', 'Building Your Professional Identity', 'Saya selalu berusaha mengembangkan diri.', 'I always try to improve myself.', 'Expression', '2026-10-03 18:12:24.759+00', '2026-10-03 18:12:24.759+00', NULL, 3, 'Workplace', 'A', '1'),
	('2e309beb-19f5-404c-95a5-181aad018fd1', 'Building Your Professional Identity', 'Saya memiliki semangat terhadap karier masa depan saya.', 'I am passionate about my future career.', 'Expression', '2026-10-03 18:12:24.759+00', '2026-10-03 18:12:24.759+00', NULL, 3, 'Workplace', 'A', '1'),
	('93028c09-e584-4460-bf97-f76c5f9ffdb7', 'Building Your Professional Identity', 'Saya siap menghadapi tantangan baru.', 'I am ready to take on new challenges.', 'Expression', '2026-10-03 18:12:24.759+00', '2026-10-03 18:12:24.759+00', NULL, 3, 'Workplace', 'A', '1'),
	('af1313ba-9a2f-4c87-b271-b26971c7956a', 'Building Your Professional Identity', 'Saya yakin dapat memberikan kontribusi yang positif.', 'I believe I can make a positive contribution.', 'Expression', '2026-10-03 18:12:24.759+00', '2026-10-03 18:12:24.759+00', NULL, 3, 'Workplace', 'A', '1'),
	('77150ce4-c78c-4cbe-a189-245517f82492', 'Building Your Professional Identity', 'Saya senang mempelajari hal-hal baru.', 'I enjoy learning new things.', 'Expression', '2026-10-03 18:12:24.759+00', '2026-10-03 18:12:24.759+00', NULL, 3, 'Workplace', 'A', '1'),
	('dc9c0572-8a25-42ee-bb18-236fec71ffb7', 'Building Your Professional Identity', 'Saya telah mengembangkan kemampuan komunikasi yang baik.', 'I have developed strong communication skills.', 'Expression', '2026-10-03 18:12:24.759+00', '2026-10-03 18:12:24.759+00', NULL, 3, 'Workplace', 'A', '1'),
	('76b791ae-bff4-49f1-9ea9-161629a1b891', 'Building Your Professional Identity', 'Izinkan saya memperkenalkan diri saya.', 'Let me tell you about myself.', 'Expression', '2026-10-03 18:12:24.759+00', '2026-10-03 18:12:24.759+00', NULL, 3, 'Workplace', 'A', '1'),
	('a588d360-ef43-4eeb-b75d-352d83514bef', 'Building Your Professional Identity', 'Tujuan saya adalah terus berkembang dalam karier.', 'My goal is to continue growing professionally.', 'Expression', '2026-10-03 18:12:24.759+00', '2026-10-03 18:12:24.759+00', NULL, 3, 'Workplace', 'A', '1'),
	('37f7e3d0-e51d-497c-ac53-63829fa95ecf', 'Building Your Professional Identity', 'Salah satu kelebihan terbesar saya adalah...', 'One of my greatest strengths is...', 'Expression', '2026-10-03 18:12:24.759+00', '2026-10-03 18:12:24.759+00', NULL, 3, 'Workplace', 'A', '1'),
	('e459da2f-9571-4243-8b4c-e167d16f4698', 'Building Your Professional Identity', 'Terima kasih telah mengenal saya.', 'Thank you for getting to know me.', 'Expression', '2026-10-03 18:12:24.759+00', '2026-10-03 18:12:24.759+00', NULL, 3, 'Workplace', 'A', '1'),
	('7fba0a88-6e6c-4a11-ac56-cbaa87d19965', 'Building Your Professional Identity', 'pencapaian', 'achievement / accomplishment', 'Noun', '2026-10-03 18:12:24.759+00', '2026-10-03 18:12:24.759+00', NULL, 3, 'Workplace', 'A', '1'),
