	('ec4829c8-b755-4dcc-bed0-fd27ec1658ed', 'Cultural Identity & Tradition', 'Rumah adalah tempat seseorang memiliki kebebasan dan merasa berkuasa/aman.', 'A man''s home is his castle.', 'Proverb', '2026-10-03 18:12:24.765+00', '2026-10-03 18:12:24.765+00', NULL, 3, 'CCU', 'C', '1'),
	('b4955ef5-ccdd-48b1-aaae-17d4a61f2c07', 'Cultural Identity & Tradition', 'Kebaikan dan kepedulian sebaiknya dimulai dari keluarga sendiri.', 'Charity begins at home.', 'Proverb', '2026-10-03 18:12:24.765+00', '2026-10-03 18:12:24.765+00', NULL, 3, 'CCU', 'C', '1'),
	('5ec95d30-42cd-424b-9096-e7a610880547', 'Cultural Identity & Tradition', 'Setiap orang memiliki cara, kebiasaan, dan pilihan yang berbeda.', 'Different strokes for different folks.', 'Proverb', '2026-10-03 18:12:24.765+00', '2026-10-03 18:12:24.765+00', NULL, 3, 'CCU', 'C', '1'),
	('8b14b53a-b980-4490-ad2b-8824dcb61f4c', 'Cultural Identity & Tradition', 'Timur dan barat memiliki perbedaan budaya dan cara hidup.', 'East is east, and west is west.', 'Proverb', '2026-10-03 18:12:24.765+00', '2026-10-03 18:12:24.765+00', NULL, 3, 'CCU', 'C', '1'),
	('4701ca50-b148-47c8-bddd-a0d922795b0a', 'Cultural Identity & Tradition', 'Sejauh apa pun bepergian, rumah sendiri tetap yang terbaik.', 'East or west, home is best.', 'Proverb', '2026-10-03 18:12:24.766+00', '2026-10-03 18:12:24.766+00', NULL, 3, 'CCU', 'C', '1'),
	('5b773446-62dd-4f73-ba28-78449d3ce3ad', 'Cultural Identity & Tradition', 'Rumah adalah tempat yang paling dekat dengan hati seseorang.', 'Home is where the heart is.', 'Proverb', '2026-10-03 18:12:24.766+00', '2026-10-03 18:12:24.766+00', NULL, 3, 'CCU', 'C', '1'),
	('c95240e4-0ca3-4a45-abc0-0f42c9ec8f18', 'Cultural Identity & Tradition', 'Hiduplah dengan damai dan biarkan orang lain menjalani hidupnya.', 'Live and let live.', 'Proverb', '2026-10-03 18:12:24.766+00', '2026-10-03 18:12:24.766+00', NULL, 3, 'CCU', 'C', '1'),
	('afaf3e8f-cb9b-46f9-89a4-f0b789a5cffd', 'Cultural Identity & Tradition', 'Setiap orang memiliki pilihan dan seleranya masing-masing.', 'To each his own.', 'Proverb', '2026-10-03 18:12:24.766+00', '2026-10-03 18:12:24.766+00', NULL, 3, 'CCU', 'C', '1'),
	('545f4ca3-2931-4e56-8710-06227b95ef13', 'Cultural Identity & Tradition', 'Keberagaman membuat kehidupan menjadi lebih menarik.', 'Variety is the spice of life.', 'Proverb', '2026-10-03 18:12:24.766+00', '2026-10-03 18:12:24.766+00', NULL, 3, 'CCU', 'C', '1'),
